/**
 * Full content sync: pushes every document generated by
 * scripts/build-sanity-seed.js to Sanity via createOrReplace (never
 * deletes anything not explicitly listed below), plus removes one
 * confirmed stray duplicate found by audit.
 *
 * Unlike `sanity dataset import --replace`, this:
 *   - runs as a single reviewable transaction,
 *   - can't fail on intra-file duplicate _ids (the seed builder's
 *     uniqueId() helper already guarantees uniqueness),
 *   - lets us delete specific known-stray documents in the same commit.
 *
 * Run from studio/:
 *   npx sanity exec scripts/full-content-sync.js --with-user-token
 */
import { readFileSync } from "node:fs";
import { getCliClient } from "sanity/cli";

const seedPath = new URL("../../scripts/sanity-seed.ndjson", import.meta.url);
const docs = readFileSync(seedPath, "utf8")
  .trim()
  .split("\n")
  .map((line) => JSON.parse(line));

// Confirmed via audit: a groupPhoto doc created directly in the Studio on
// 2026-07-28 with a random _id, duplicating caption+image of the
// deterministic-id "groupPhoto-group-photo-2026-jul-25" doc already in the
// seed above. Same pattern as the two facility duplicates removed earlier.
const STRAY_IDS = ["47fee234-bd49-4bca-9597-cc338b33292b"];

const client = getCliClient({ apiVersion: "2023-08-01" });

async function main() {
  const tx = client.transaction();
  docs.forEach((doc) => tx.createOrReplace(doc));
  STRAY_IDS.forEach((id) => tx.delete(id));

  const result = await tx.commit();
  console.log(
    `Committed ${result.results.length} operations ` +
      `(${docs.length} createOrReplace, ${STRAY_IDS.length} delete).`
  );
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
